select  from operation_log

  and operator_name like concat('%', #{operatorName}, '%')
  and module = #{module}
  and action = #{action}
  and create_time >= #{startTime}
  and create_time <= #{endTime}

order by create_time desc
limit #{offset}, #{limit}

select count(*) from operation_log

  and operator_name like concat('%', #{operatorName}, '%')
  and module = #{module}
  and action = #{action}
  and create_time >= #{startTime}
  and create_time <= #{endTime}
